def fill_symmetry_v2(grid):
    """Fill 2's by propagating values through symmetry."""
    h = len(grid)
    w = len(grid[0])
    result = [row[:] for row in grid]

    # First, find all non-2 positions
    non2_pos = {}
    for r in range(h):
        for c in range(w):
            if result[r][c] != 2:
                non2_pos[(r, c)] = result[r][c]

    # For each 2, look at symmetric positions
    for r in range(h):
        for c in range(w):
            if result[r][c] == 2:
                val = None
                positions = [(r, c), (r, w-1-c), (h-1-r, c), (h-1-r, w-1-c)]

                for sr, sc in positions:
                    if (sr, sc) in non2_pos:
                        val = result[sr][sc]
                        break

                if val is not None:
                    result[r][c] = val

    return result

